        {
            new Quote { Id = "https://de.wikiquote.org/wiki/Thomas_Mann", Text = "Brave, herrliche junge Leute! Ihr seid nicht umsonst gestorben, sollt nicht vergessen sein", Author = "Thomas Mann" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Thomas_Mann", Text = "Die Rolle des Vertrauten ist immer zugleich wohltuend und schmerzlich, denn man spielt sie ja immer nur unter der Voraussetzung, daß man selbst nicht in Betracht kommt. Aber wieviel besser ist es doch, habe ich mir oft gesagt, der Welt Vertrauen einzuflößen, als ihre Leidenschaften zu erregen! Wieviel besser, ihr 'gut', als ihr 'schön' zu erscheinen!", Author = "Thomas Mann" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Thomas_Mann", Text = "Fahr hin, jovialer Mordwanst! Du hast es wenigstens genossen, während dein Herr und Meister nie nirgends gelebt hat als in der Hölle.", Author = "Thomas Mann" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Thomas_Mann", Text = "München leuchtete. Über den festlichen Plätzen und weißen Säulentempeln, den antikisierenden Monumenten und Barockkirchen, den springenden Brunnen, Palästen und Gartenanlagen der Residenz spannte sich strahlend ein Himmel von blauer Seide, und ihre breiten und lichten, umgrünten und wohlberechneten Perspektiven lagen in dem Sonnendunst eines ersten, schönen Junitages.", Author = "Thomas Mann" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Thomas_Mann", Text = "Sagt, was ihr wollt: das Christentum, diese Blüte des Judentums, bleibt einer der beiden Grundpfeiler, auf denen die abendländische Gesittung ruht und von denen die andere die mediterrane Antike ist. Die Verleugnung einer dieser Grundvoraussetzungen unserer Sittlichkeit und Bildung, oder gar ihrer beider, durch irgendeine Gruppe der abendländischen Gemeinschaft würde ihr Ausscheiden aus dieser und eine unvorstellbare, übrigens gottlob gar nicht nachvollziehbare Zurückschraubung ihrer humanen Status, ich weiß nicht, wohin, bedeuten", Author = "Thomas Mann" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Thomas_Mann", Text = "So hoch er sich heute spreizt, so weit seine Einschüchterung sich ausbreitet, soviel von ihm angerichtetes Elend, Entehrung, Verderbnis, Blut, Tränen, Verzweiflung und Selbstmord er sich von seinem Bergsitz betrachten und sich groß, sich »geschichtlich« vorkommen darf, – der Stab ist ihm gebrochen, nichts wird bleiben von seinen Worten und Werken, weil sie falsch und nichtig waren, und sein Nachruhm wird Schande sein.", Author = "Thomas Mann" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Thomas_Mann", Text = "Welch eine herrliche Gabe ist nicht die Phantasie, und welchen Genuß vermag sie zu gewähren!", Author = "Thomas Mann" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Thomas_Mann", Text = "heute [kann] nichts Lebendiges die Politik umgehen [...]. Selbst eine Weigerung zur Politik ist politisch; sie fördert lediglich die Politik des Bösen.", Author = "Thomas Mann" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Thomas_Mann", Text = "Ich habe es mir nicht träumen lassen, daß ich meine höheren Tage als Emigrant, zu Hause enteignet und verfemt, in tief notwendigem politischen Protest verbringen würde.", Author = "Thomas Mann" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Thomas_Mann", Text = "Der einfache Gedanke daran, wer die Menschen sind, denen die erbärmlich-äußerliche Zufallsmacht gegeben ist, mir mein Deutschtum abzusprechen, reicht hin, diesen Akt in seiner ganzen Lächerlichkeit erscheinen zu lassen. [...] Sie haben die unglaubwürdige Kühnheit, sich mit Deutschland zu verwechseln!", Author = "Thomas Mann" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Thomas_Mann", Text = "Reduziert auf ein elendes Massenniveau, das Niveau eines Hitler, brach die deutsche Romantik in hysterische Barbarei aus", Author = "Thomas Mann" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Thomas_Mann", Text = "Auf irgendeine Weise fehlte es der Atmosphäre an Unschuld, an Zwanglosigkeit […] Man verstand bald, daß Politisches umging, die Idee der Nation im Spiel war.", Author = "Thomas Mann" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Thomas_Mann", Text = "Die Freiheit existiert, und auch der Wille existiert; aber die Willensfreiheit existiert nicht, denn ein Wille, der sich auf seine Freiheit richtet, stößt ins Leere.", Author = "Thomas Mann" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Thomas_Mann", Text = "Wahrscheinlich kann man vom Nichtwollen seelisch nicht leben; eine Sache nicht tun wollen, das ist auf Dauer kein Lebensinhalt.", Author = "Thomas Mann" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Thomas_Mann", Text = "Dem Problem der Toleranz dürften Sie kaum gewachsen sein, Ingenieur. Prägen Sie sich immerhin ein, daß Toleranz zum Verbrechen wird, wenn sie dem Bösen gilt.", Author = "Thomas Mann" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Thomas_Mann", Text = "Der Mensch soll um der Güte und Liebe willen dem Tode keine Herrschaft einräumen über seine Gedanken.", Author = "Thomas Mann" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Thomas_Mann", Text = "Der große Mann ist ein öffentliches Unglück.", Author = "Thomas Mann" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Thomas_Mann", Text = "Ein gutes Buch werde gleich zusammen mit seinem Titel geboren.", Author = "Thomas Mann" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Thomas_Mann", Text = "Ironie [...] ist das Körnchen Salz, durch welches das Aufgetischte überhaupt erst genießbar wird.", Author = "Thomas Mann" },
